pub fn process_arg_overrides<'b>(
    &mut self,
    a: Option<&AnyArg<'a, 'b>>,
    overrides: &mut Vec<(&'b str, &'a str)>,
    required: &mut Vec<&'a str>,
    check_all: bool,
) {
    debugln!(
